package local.tvmorph.tv;
import android.content.Context;import org.json.*;
/** Native player-browser mirror of local hidden IDs. No PIN, subscription credentials or provider edits. */
final class IptvParentalStore {
 private static JSONObject state(Context context){try{JSONObject info=IptvStore.get(context).summary();String scope=info.optString("profileId","default")+"@default";JSONObject value=new JSONObject(context.getSharedPreferences("morph-iptv-parental",0).getString("scopes","{}")).optJSONObject(scope);return value==null?new JSONObject():value;}catch(Exception ignored){return new JSONObject();}}
 private static String category(JSONObject item){String value=item.optString("seriesCategory");if(value.isEmpty())value=item.optString("category_id");if(value.isEmpty())value=item.optString("categoryId");if(value.isEmpty()&&!item.optString("kind").equals("episode"))value=item.optString("category");return value;}
 private static String[] keys(JSONObject item){String kind=item.optString("kind"),id=item.optString("id"),parent=item.optString("seriesId");if(parent.isEmpty())parent=item.optString("category");return new String[]{kind+":"+id,"category:"+(kind.equals("episode")?"series":kind)+":"+category(item),kind.equals("episode")?"series:"+parent:""};}
 static boolean restricted(Context context,JSONObject item){JSONObject state=state(context),rules=state.optJSONObject("rules");if(rules==null)return false;for(String key:keys(item)){JSONObject r=rules.optJSONObject(key);if(r!=null&&(r.optBoolean("hidden")||state.optBoolean("enabled")&&(r.optBoolean("locked")||r.optLong("until",0)>0&&System.currentTimeMillis()>=r.optLong("until"))))return true;}return false;}
 static long deadline(Context context,JSONObject item){JSONObject state=state(context),rules=state.optJSONObject("rules");long deadline=0;if(!state.optBoolean("enabled")||rules==null)return 0;for(String key:keys(item)){JSONObject r=rules.optJSONObject(key);long until=r==null?0:r.optLong("until",0);if(until>System.currentTimeMillis()&&(deadline==0||until<deadline))deadline=until;}return deadline;}
 static void sync(Context context,String raw){try{if(raw==null||raw.length()>2000000)return;JSONObject value=new JSONObject(raw);JSONObject scopes=value.optJSONObject("scopes");if(scopes==null)return;context.getSharedPreferences("morph-iptv-parental",0).edit().putString("scopes",scopes.toString()).apply();}catch(Exception ignored){}}
 private static JSONObject rules(Context context){try{JSONObject info=IptvStore.get(context).summary();String scope=info.optString("profileId","default")+"@default";JSONObject state=new JSONObject(context.getSharedPreferences("morph-iptv-parental",0).getString("scopes","{}")).optJSONObject(scope);return state==null?new JSONObject():state.optJSONObject("rules");}catch(Exception ignored){return new JSONObject();}}
 private static boolean hidden(JSONObject rules,String key){JSONObject rule=rules==null?null:rules.optJSONObject(key);return rule!=null&&rule.optBoolean("hidden");}
 static JSONArray filter(Context context,JSONArray rows,String kind,boolean categories){JSONObject rules=rules(context);JSONArray output=new JSONArray();if(rows==null)return output;for(int i=0;i<rows.length();i++){JSONObject item=rows.optJSONObject(i);if(item==null)continue;String type=item.optString("kind",kind),id=item.optString("id",item.optString("category_id")),category=category(item);String group=type.equals("episode")?"series":type;boolean hide=categories?hidden(rules,"category:"+kind+":"+item.optString("category_id",id)):hidden(rules,type+":"+id)||hidden(rules,"category:"+group+":"+category)||type.equals("episode")&&hidden(rules,"series:"+item.optString("seriesId",category));if(!hide)output.put(item);}return output;}
}
